import { Component } from "react";

import * as FieldDimensions from "./FieldDimensions";
type Props = object;

type State = object;
const red = "rgb(162,0,16)";
const blue = "rgb(0,72,167)";
const white = "rgb(204,204,204)";
const green = "rgb(76,175,80)";
const gray = "rgb(66,66,66)";
const purple = "rgb(156,39,176)";
export default class FieldImage2024 extends Component<Props, State> {
  WIDTH_M = FieldDimensions.FIELD_WIDTH;
  LENGTH_M = FieldDimensions.FIELD_LENGTH;
  state = {};

  render() {
    return (
      <g id="layer1" transform={`scale(1, -1) translate(0,${-this.WIDTH_M})`}>
        <g
          id="img"
          transform={`scale(${this.WIDTH_M / 1796})`}
          opacity={"100%"}
          style={{
            fillRule: "evenodd",
            clipRule: "evenodd",
            strokeLinecap: "round",
            strokeLinejoin: "round",
            strokeMiterlimit: 1.5
          }}
        >
          <image href="data:image/jpg;base64,"/>
        </g>
      </g>
    );
  }
}
